top10 as (
  select c.embedding from public.catalog_items c, q
  where c.embedding is not null order by c.embedding <=> q.v limit 10
),
cen as (select avg(embedding) as c from top10),
a as (
  select 'A atual' as variante, ci.title, s.name as fonte, ci.tags::text as tags,
         round((1 - (ci.embedding <=> q.v))::numeric, 4) as sim
  from public.catalog_items ci, q, public.sources s
  where s.id = ci.source_id and ci.embedding is not null
  order by ci.embedding <=> q.v limit 30
),
b as (
  select 'B refinada' as variante, ci.title, s.name as fonte, ci.tags::text as tags,
         round((1 - (ci.embedding <=> q.v))::numeric, 4) as sim
  from public.catalog_items ci, q, cen, public.sources s
  where s.id = ci.source_id and ci.embedding is not null
  order by (ci.embedding <=> q.v) + (ci.embedding <=> cen.c) limit 30
)
select variante, row_number() over (partition by variante order by sim desc) as n, title, fonte, tags, sim
from (select * from a union all select * from b) x
order by variante, n;
